import React, { useEffect } from 'react';
import './main.css';
import { initMainEffects } from './main.js';

function Main({ children }) {
  useEffect(() => {
    initMainEffects();
  }, []);

  return (
    <main className="bb-main">
      <div className="container bb-main__container">{children}</div>

      {/* Anchors for header navigation */}
      <div id="products" style={{ display: 'none' }} />
      <div id="news" style={{ display: 'none' }} />
      <div id="categories" style={{ display: 'none' }} />
    </main>
  );
}

export default Main;
